def runs_for_text(text, force_highlight=False, bold=False):
    """Split on «..» markers -> highlighted runs; force_highlight highlights all."""
    rpr_common = '<w:b/>' if bold else ''
    out = []
    i = 0
    while i < len(text):
        if not force_highlight and text[i] == HL_OPEN:
            j = text.find(HL_CLOSE, i + 1)
            seg = text[i + 1:j]
            rpr = f'<w:rPr>{rpr_common}<w:highlight w:val="yellow"/></w:rPr>'
            out.append(f'<w:r>{rpr}<w:t xml:space="preserve">{escape(seg)}</w:t></w:r>')
            i = j + 1
        else:
            j = len(text) if force_highlight else text.find(HL_OPEN, i)
            if j == -1:
                j = len(text)
            seg = text[i:j]
            if seg:
                hl = '<w:highlight w:val="yellow"/>' if force_highlight else ''
                rpr = f'<w:rPr>{rpr_common}{hl}</w:rPr>' if (rpr_common or hl) else ''
                out.append(f'<w:r>{rpr}<w:t xml:space="preserve">{escape(seg)}</w:t></w:r>')
            i = j
    return ''.join(out)

def para_xml(style, text, highlight):
    bold = False
    if style == "title":
        ppr = '<w:pPr><w:jc w:val="center"/><w:spacing w:after="120"/></w:pPr>'; bold = True
    elif style == "author":
        ppr = '<w:pPr><w:jc w:val="center"/></w:pPr>'
    elif style == "affil":
        ppr = '<w:pPr><w:jc w:val="center"/><w:spacing w:after="120"/></w:pPr>'
    elif style == "h1":
        ppr = '<w:pPr><w:spacing w:before="180" w:after="80"/></w:pPr>'; bold = True
    elif style == "caption":
        ppr = '<w:pPr><w:jc w:val="center"/><w:spacing w:before="60" w:after="60"/></w:pPr>'
    else:
        ppr = '<w:pPr><w:spacing w:after="120"/><w:jc w:val="both"/></w:pPr>'
    return f'<w:p>{ppr}{runs_for_text(text, force_highlight=highlight, bold=bold)}</w:p>'

